(()=>{const projects=[...document.querySelectorAll('.work-content .project')],links=[...document.querySelectorAll('[data-jump]')];function count(){document.querySelector('#work-count').textContent=`SHOWING ${String(projects.filter(p=>!p.hidden).length).padStart(2,'0')} PROJECTS`}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',count));links.forEach(a=>a.addEventListener('click',()=>{document.querySelector('[data-filter="all"]').click();document.querySelector('#work-'+a.dataset.jump).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}));if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){links.forEach(a=>{const selected=a.dataset.jump===e.target.dataset.project;a.classList.toggle('current',selected);if(selected)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}})},{rootMargin:'-15% 0px -45% 0px',threshold:0});projects.forEach(p=>observer.observe(p))}count()})();
